console.log('👍')
var nav = document.querySelector('.nav'),
	navBtn = document.querySelector('.hamburger'),
	navMobile = document.querySelector('.navbar__mobile'),
	navItems = navMobile.querySelectorAll('.navbar__item'),
	shadow = document.querySelector('.shadow'),
	footerYear = document.querySelector('.footer__year'),
	scrollToTopBtn = document.querySelector('.scroll-to-top-btn'),
	root = document.documentElement,
	// contactInputs = document.querySelectorAll('.contact__form-input'),
	contactTextArea = document.querySelector('.contact__form-text'),
	contactLabels = document.querySelectorAll('.contact__form-label'),
	handleNav = function () {
		navBtn.classList.toggle('is-active'),
			navMobile.classList.toggle('navbar__mobile--active'),
			document.body.classList.toggle('fixed-body')
	},
	handleScrollBar = function () {
		var e = window.scrollY,
			t = document.body.getBoundingClientRect().height - window.innerHeight,
			e = Math.floor((e / t) * 100)
		root.style.setProperty('--scroll-width', ''.concat(e, '%')),
			10 < e ? nav.classList.add('nav--active') : nav.classList.remove('nav--active'),
			95 < e
				? scrollToTopBtn.classList.add('scroll-to-top-btn--active')
				: scrollToTopBtn.classList.remove('scroll-to-top-btn--active')
	},
	handleLabel = function (e) {
		'' == e.target.value && e.target.nextElementSibling.classList.toggle('contact__form-label--active')
	},
	handleCurrentYear = function () {
		var e = new Date().getFullYear()
		footerYear.innerText = e
	}
handleCurrentYear(),
	window.addEventListener('scroll', handleScrollBar),
	navBtn.addEventListener('click', handleNav),
	shadow.addEventListener('click', handleNav),
	navItems.forEach(function (e) {
		return e.addEventListener('click', handleNav)
	})

